/**
 * src/models/Request.js
 *
 * A Request is the runtime instance of a workflow for a specific student.
 * One Request is created each time a student submits a service request.
 *
 * Key design decisions:
 *
 * 1. requestNumber — human-readable unique ID (e.g. "UF-20251014-A3X7").
 *    Generated by a pre-save hook so it is never null on the first save.
 *
 * 2. runtimeSteps — embedded array mirroring the Workflow.steps definition,
 *    with added runtime fields (actor, comment, actionedAt, status).
 *    Storing them embedded (not as separate documents) keeps the full
 *    history retrievable in a single document fetch.
 *
 * 3. auditLog — append-only array of events. Every status transition appends
 *    one entry. This gives a complete, tamper-evident audit trail.
 *
 * 4. formData — flexible object (Mixed type) that holds the student's
 *    submitted form values. Different services have different fields.
 *
 * 5. workflowVersion — snapshot of the workflow version at submission time,
 *    so the approval chain does not change if the workflow definition is updated.
 */

import mongoose, { Schema } from 'mongoose';

// ─── Constants ────────────────────────────────────────────────────────────────

export const REQUEST_STATUSES = Object.freeze([
  'SUBMITTED',
  'DEPARTMENT_VERIFICATION_PENDING',
  'SECURITY_REVIEW_PENDING',
  'PAYMENT_REQUIRED',
  'ADMIN_APPROVAL_PENDING',
  'STAFF_REVIEW_PENDING',
  'BOOKING_CONFIRMED',
  'COMPLETED',
  'REJECTED',
]);

export const STEP_STATUSES = Object.freeze({
  PENDING: 'PENDING',
  APPROVED: 'APPROVED',
  REJECTED: 'REJECTED',
  PAYMENT_PENDING: 'PAYMENT_PENDING',
  PAYMENT_COMPLETED: 'PAYMENT_COMPLETED',
});

// ─── Sub-schemas ──────────────────────────────────────────────────────────────

// Runtime step — one entry per workflow step definition
const runtimeStepSchema = new Schema(
  {
    stepIndex: { type: Number, required: true },
    name: { type: String, required: true, trim: true },
    assignedRole: { type: String, required: true },
    isPaymentStep: { type: Boolean, default: false },

    status: {
      type: String,
      required: true,
      enum: Object.values(STEP_STATUSES),
      default: STEP_STATUSES.PENDING,
    },

    // The user who actioned this step (null until actioned)
    actor: { type: Schema.Types.ObjectId, ref: 'User', default: null },
    comment: { type: String, trim: true, default: null },
    actionedAt: { type: Date, default: null },
  },
  { _id: false }
);

// Audit log entry — append-only; never updated
const auditEventSchema = new Schema(
  {
    timestamp: { type: Date, default: Date.now },
    actor: { type: Schema.Types.ObjectId, ref: 'User', default: null },
    action: {
      type: String,
      required: true,
      enum: ['SUBMITTED', 'APPROVED', 'REJECTED', 'PAYMENT_COMPLETED', 'CANCELLED'],
    },
    stepIndex: { type: Number, default: null },
    comment: { type: String, default: null },
    previousStatus: { type: String, default: null },
    newStatus: { type: String, required: true },
  },
  { _id: false }
);

// ─── Request schema ───────────────────────────────────────────────────────────

const requestSchema = new Schema(
  {
    requestNumber: {
      type: String,
      unique: true,
      // Set by pre-save hook; not supplied by client
    },

    student: {
      type: Schema.Types.ObjectId,
      ref: 'User',
      required: [true, 'Request must have a student.'],
    },

    service: {
      type: Schema.Types.ObjectId,
      ref: 'Service',
      required: [true, 'Request must reference a service.'],
    },

    institution: {
      type: Schema.Types.ObjectId,
      ref: 'Institution',
      required: [true, 'Request must belong to an institution.'],
    },

    workflow: {
      type: Schema.Types.ObjectId,
      ref: 'Workflow',
      required: [true, 'Request must reference a workflow.'],
    },

    // Snapshot of the workflow version at submission time
    workflowVersion: {
      type: Number,
      required: [true, 'Workflow version must be recorded at submission.'],
    },

    status: {
      type: String,
      required: true,
      enum: {
        values: REQUEST_STATUSES,
        message: `Status must be one of: ${REQUEST_STATUSES.join(', ')}.`,
      },
      default: 'SUBMITTED',
    },

    // Index of the step currently awaiting action (0-based)
    currentStepIndex: {
      type: Number,
      default: 0,
      min: [0, 'Step index cannot be negative.'],
    },

    // Student-submitted form values — shape varies by service
    formData: {
      type: Schema.Types.Mixed,
      default: {},
    },

    // Runtime copy of workflow steps with per-step status tracking
    runtimeSteps: {
      type: [runtimeStepSchema],
      default: [],
    },

    // Append-only audit trail
    auditLog: {
      type: [auditEventSchema],
      default: [],
    },
  },
  {
    timestamps: true,
    collection: 'requests',
  }
);

// ─── Indexes ──────────────────────────────────────────────────────────────────

// Note: requestNumber unique index is created by `unique: true` on the field above.
requestSchema.index({ student: 1, createdAt: -1 });
requestSchema.index({ status: 1 });
requestSchema.index({ institution: 1, status: 1, createdAt: -1 });
requestSchema.index({ 'runtimeSteps.assignedRole': 1, status: 1 });

// ─── Pre-save hook: generate requestNumber ────────────────────────────────────

requestSchema.pre('save', function (next) {
  if (this.isNew && !this.requestNumber) {
    const now = new Date();
    const datePart = [
      now.getFullYear(),
      String(now.getMonth() + 1).padStart(2, '0'),
      String(now.getDate()).padStart(2, '0'),
    ].join('');
    // 6-char random alphanumeric suffix — collision probability negligible for demo scale
    const randomPart = Math.random().toString(36).slice(2, 8).toUpperCase();
    this.requestNumber = `UF-${datePart}-${randomPart}`;
  }
  next();
});

export default mongoose.model('Request', requestSchema);
